class Solution:
    def countWays(self, nums: List[int]) -> int:
        nums.sort()
        ans = 0
        for k in range(len(nums) + 1):
            if (k == 0 or nums[k - 1] < k) and (k == len(nums) or nums[k] > k):
                ans += 1
        return ans

c.cpp:
class Solution {
public:
    int countWays(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int ans = 0, n = nums.size();
        for (int k = 0; k <= n; k++)
            if ((k == 0 || nums[k - 1] < k) && (k == n || nums[k] > k)) ans++;
        return ans;
    }
};

