class Solution {
    public int countWays(List<Integer> nums) {
        Collections.sort(nums);
        int ans = 0, n = nums.size();
        for (int k = 0; k <= n; k++)
            if ((k == 0 || nums.get(k - 1) < k) && (k == n || nums.get(k) > k)) ans++;
        return ans;
    }
}

